inline std::array<int, 16> chromosome(const std::string &x, const std::string &y) {
    if (x.size() != y.size())
        throw std::invalid_argument("unaligned chromosome");
    std::array<int, 16> sums{};
    int firstx = -1, firsty = -1, lastx = -1, lasty = -1;
    for (size_t i = 0; i < x.size(); ++i) {
        int a = x[i] - '0', b = y[i] - '0';
        if (a < 0 || a > 8 || b < 0 || b > 8)
            throw std::invalid_argument("invalid digit");
        if (a == 0 || b == 0)
            continue;
        if (firstx < 0) {
            firstx = a;
            firsty = b;
        } else {
            int j = (a - lastx + 7) * 15 + (b - lasty + 7);
            for (int k = 0; k < 16; ++k)
                sums[k] += EDGE[k][j];
        }
        lastx = a;
        lasty = b;
    }
    if (firstx >= 0) {
        int left = (firstx - 1) * 8 + (firsty - 1), right = (lastx - 1) * 8 + (lasty - 1);
        for (int k = 0; k < 16; ++k)
            sums[k] = (sums[k] + END[k][left] + END[k][right] + 1) / 2;
    }
    return sums;
}
